    local logo = Instance.new("ImageLabel")
    logo.Name = "PrimeLogo"
    logo.Size = UDim2.fromOffset(size, size)
    logo.BackgroundTransparency, logo.BorderSizePixel = 1, 0
    logo.ScaleType = Enum.ScaleType.Fit
    logo.ImageRectOffset = Vector2.new(0, 39)
    logo.ImageRectSize = Vector2.new(1218, 1135)
    logo.Active, logo.Selectable, logo.ZIndex = false, false, 3
    logo.Parent = parent
    if logoAsset then
        logo.Image = logoAsset
    else
        logoWaiters[#logoWaiters + 1] = logo
        if not logoLoading then
            logoLoading = true
            task.spawn(function()
                local asset = loadLogoAsset(function() return not ScriptUnloaded end)
                logoLoading = false
                if asset and not ScriptUnloaded then
                    logoAsset = asset
                    for _, waiting in ipairs(logoWaiters) do
                        if waiting.Parent then waiting.Image = asset end
                    end
                end
                table.clear(logoWaiters)
            end)
        end
    end
    return logo
end
RegisterUnloadCallback(function()
    table.clear(logoWaiters)
    logoAsset = nil
end)
RegisterUnloadCallback(function()
    table.clear(bindings)
    table.clear(NexusUI.ThemeRefresh)
end)

function ApplyButtonStyle(button)
    if not button then return end
    if button:IsA("TextButton") then
        button.AutoButtonColor = false
        button.SelectionImageObject = nil
    end
    if button:IsA("GuiObject") then
        button.Active = true
    end
end


function CreateClickButton(parent, text, size, position, bgColor, textColor, font, textSize, disableHover)
    local bgRole = colorRoles[bgColor] or 5
    local textRole = colorRoles[textColor] or 7
    local button = Instance.new("Frame")
    button.Size = size
    button.Position = position
    NexusUI:BindColor(button, "BackgroundColor3", function() return NexusUI.Palette[bgRole] end)
    button.BackgroundTransparency = GUI_BUTTON_TRANSPARENCY
    button.BorderSizePixel = 0
    button.Active = true
    button.ClipsDescendants = true
    button:SetAttribute("BlockWindowDrag", true)
    button.ZIndex = 10
    button.Parent = parent

    local label = Instance.new("TextLabel")
    label.Size = UDim2.new(1, 0, 1, 0)
    label.BackgroundTransparency = 1
    label.Text = text or ""
    NexusUI:BindColor(label, "TextColor3", function() return NexusUI.Palette[textRole] end)
    label.FontFace = Font.new(FONT_BODY, font == Enum.Font.GothamBold and Enum.FontWeight.Bold or Enum.FontWeight.SemiBold, Enum.FontStyle.Normal)
    label.TextSize = (textSize or 14) + 1
    label.TextXAlignment = Enum.TextXAlignment.Center
    label.TextYAlignment = Enum.TextYAlignment.Center
    label.ZIndex = 11
    label.Parent = button

    local buttonCorner = Instance.new("UICorner")
    buttonCorner.CornerRadius = UDim.new(0, 6)
    buttonCorner.Parent = button

    local defaultBackground = button.BackgroundColor3
    local hoverBackground = defaultBackground:Lerp(ACCENT, 0.12)
    local pressedBackground = defaultBackground:Lerp(ACCENT, 0.22)
    table.insert(NexusUI.ThemeRefresh, function()
        if not button.Parent then return end
        defaultBackground = NexusUI.Palette[bgRole]
        hoverBackground = defaultBackground:Lerp(ACCENT, 0.12)
        pressedBackground = defaultBackground:Lerp(ACCENT, 0.22)
    end)
    local hovered = false
    local pressed = false

    local function tweenBackground(color)
        if button and button.Parent then
            TweenService:Create(button, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = color}):Play()
        end
    end

    if not disableHover then
        TrackGuiConnection(button.MouseEnter:Connect(function()
            hovered = true
            if not pressed then
                tweenBackground(hoverBackground)
            end
        end))

        TrackGuiConnection(button.MouseLeave:Connect(function()
            hovered = false
            if not pressed then
                tweenBackground(defaultBackground)
            end
        end))

        TrackGuiConnection(button.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                pressed = true
                tweenBackground(pressedBackground)
            end
        end))

        TrackGuiConnection(button.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                pressed = false
                tweenBackground(hovered and hoverBackground or defaultBackground)
            end
        end))
    end

    return button, label
end

function ConnectClick(button, callback)
    if not button then return end
    local pressed = false

    local function isClickInput(input)
        return input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
    end

    local beganConn = button.InputBegan:Connect(function(input)
        if isClickInput(input) then
            pressed = true
        end
    end)

    local endedConn = button.InputEnded:Connect(function(input)
        if isClickInput(input) and pressed then
            pressed = false
            if callback then
                pcall(callback)
            end
        end
    end)

    if beganConn then
        table.insert(GuiConnections, beganConn)
    end
    if endedConn then
        table.insert(GuiConnections, endedConn)
    end
end

function NexusUI:CreateWindow(options)
    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "NexusMarvelOmegaUI"
    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    screenGui.ResetOnSpawn = false
    screenGui:SetAttribute("CompactMinimizeOnPC", true)
    local useCompactRestore = IS_MOBILE or screenGui:GetAttribute("CompactMinimizeOnPC") == true
    screenGui.Parent = GuiParent
    attachTextStyler(screenGui)

    local isVisibleByDefault = options == nil or options.visible ~= false
    local mainFrame = Instance.new("Frame")
    mainFrame.Name = "MainFrame"
    local requestedSize = IS_MOBILE and (options and options.Size or UDim2.fromOffset(620, 370)) or DESKTOP_WINDOW_SIZE
    local preferredSize = Vector2.new(requestedSize.X.Offset, requestedSize.Y.Offset)
    local userResized = false
    mainFrame.Size = requestedSize
    mainFrame.Position = options and options.Position or UDim2.fromOffset(40, 40)
    mainFrame.Visible = isVisibleByDefault
    mainFrame.BackgroundColor3 = Color3.new(1, 1, 1)
    windowGradient().Parent = mainFrame
    mainFrame.BackgroundTransparency = MAIN_WINDOW_TRANSPARENCY
    mainFrame.BorderSizePixel = 0
    mainFrame.ClipsDescendants = false
    mainFrame.Parent = screenGui
    local fit = Instance.new("UIScale")
    fit.Name = "NexusWindowScale"
    local targetScale = 1
    fit.Parent = mainFrame
    local cameraConnection
    local function fitWindow()
        local c = Workspace.CurrentCamera
        if not c then return end
        local v = c.ViewportSize
        if IS_MOBILE and v.X < 600 and not userResized then
            mainFrame.Size = UDim2.fromOffset(math.min(410, v.X - 24), math.min(540, v.Y - 64))
        else
            mainFrame.Size = UDim2.fromOffset(preferredSize.X, preferredSize.Y)
        end
        targetScale = IS_MOBILE and math.min(1, math.max(0.1, (v.X - 24) / mainFrame.Size.X.Offset), math.max(0.1, (v.Y - 64) / mainFrame.Size.Y.Offset)) or 1
        fit.Scale = targetScale
        local pos = mainFrame.Position
        mainFrame.Position = UDim2.fromOffset(math.clamp(pos.X.Offset, 8, math.max(8, v.X - mainFrame.Size.X.Offset * fit.Scale - 8)), math.clamp(pos.Y.Offset, 8, math.max(8, v.Y - mainFrame.Size.Y.Offset * fit.Scale - 48)))
    end
    local function bindCamera()
        if cameraConnection then cameraConnection:Disconnect() end
        if Workspace.CurrentCamera then cameraConnection = TrackGuiConnection(Workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(fitWindow)) end
        fitWindow()
    end
    TrackGuiConnection(Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(bindCamera))
    bindCamera()


    local mainCorner = corner(mainFrame, 12)
    mainCorner.Name = "NexusMainCorner"
    local mainStroke = new("UIStroke", {Name = "NexusMainStroke", ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Color = WHITE, Thickness = 1, LineJoinMode = Enum.LineJoinMode.Round}, mainFrame)
    borderGradient().Parent = mainStroke
    new("ImageLabel", {Name = "Shadow", Image = shadowAsset or "", ImageColor3 = Color3.new(), ScaleType = Enum.ScaleType.Slice, SliceCenter = Rect.new(42, 42, 50, 50), SliceScale = 2, Size = UDim2.new(1, 88, 1, 88), Position = UDim2.fromOffset(-44, -44), BackgroundTransparency = 1, Active = false, ZIndex = 0}, mainFrame)
    local innerClip = new("Frame", {Name = "InnerClip", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ClipsDescendants = true}, mainFrame)
    corner(innerClip, 12)
    createImageBackground(innerClip)
    local shade = bind(new("Frame", {Name = "Shade", Size = UDim2.fromScale(1, 1), BorderSizePixel = 0, ZIndex = 2}, innerClip), "BackgroundColor3", function() return Color3.fromRGB(9, 9, 12) end)
    corner(shade, 12)
    new("UIGradient", {Rotation = 90, Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.5), NumberSequenceKeypoint.new(0.21, 1), NumberSequenceKeypoint.new(0.87, 1), NumberSequenceKeypoint.new(1, 0.5)})}, shade)
    bind(new("UIGradient", {Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.1, 0.3), NumberSequenceKeypoint.new(0.3, 0.25), NumberSequenceKeypoint.new(0.6, 1), NumberSequenceKeypoint.new(1, 1)})},
        new("Frame", {Name = "Edge", Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 6}, innerClip)), "Color", function() return ColorSequence.new(ACCENT2, ACCENT) end)

    local animationDuration = 0.18
    local function animateWindowIn()
        if not mainFrame or not mainFrame.Parent then return end
        if not mainFrame:FindFirstChild("NexusWindowScale") then
            local windowScale = Instance.new("UIScale")
            windowScale.Name = "NexusWindowScale"
            windowScale.Scale = 0.96 * targetScale
            windowScale.Parent = mainFrame
        end

        local windowScale = mainFrame:FindFirstChild("NexusWindowScale")
        if windowScale then
            windowScale.Scale = 0.96 * targetScale
            TweenService:Create(windowScale, TweenInfo.new(animationDuration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Scale = targetScale}):Play()
        end
        TweenService:Create(mainFrame, TweenInfo.new(animationDuration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundTransparency = MAIN_WINDOW_TRANSPARENCY}):Play()
    end

    local function animateWindowOut(callback)
        if not mainFrame or not mainFrame.Parent then
            if callback then callback() end
            return
        end
        if not mainFrame:FindFirstChild("NexusWindowScale") then
            local windowScale = Instance.new("UIScale")
            windowScale.Name = "NexusWindowScale"
            windowScale.Scale = targetScale
            windowScale.Parent = mainFrame
        end

        local windowScale = mainFrame:FindFirstChild("NexusWindowScale")
        if windowScale then
            TweenService:Create(windowScale, TweenInfo.new(animationDuration, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.96 * targetScale}):Play()
        end
        TweenService:Create(mainFrame, TweenInfo.new(animationDuration, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {BackgroundTransparency = MAIN_WINDOW_TRANSPARENCY}):Play()
        task.delay(animationDuration, function()
            if callback then callback() end
        end)
    end

    local topBarHeight = 44
    local topBar = new("Frame", {Name = "TopBar", Size = UDim2.new(1, 0, 0, topBarHeight), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 4, Active = true}, innerClip)
    bind(new("Frame", {Size = UDim2.new(1, 0, 0, 1), Position = UDim2.new(0, 0, 1, -1), BackgroundTransparency = 0.925, BorderSizePixel = 0, ZIndex = 3}, topBar), "BackgroundColor3", textColor)

    local logoContainer = Instance.new("Frame")
    logoContainer.Name = "LogoContainer"
    logoContainer.Size = UDim2.new(0, 0, 1, 0)
    logoContainer.AutomaticSize = Enum.AutomaticSize.X
    logoContainer.Position = UDim2.new(0, 14, 0, 0)
    logoContainer.BackgroundTransparency = 1
    logoContainer.ZIndex = 3
    logoContainer.Parent = topBar

    local logoLayout = Instance.new("UIListLayout")
    logoLayout.FillDirection = Enum.FillDirection.Horizontal
    logoLayout.Padding = UDim.new(0, 8)
    logoLayout.SortOrder = Enum.SortOrder.LayoutOrder
    logoLayout.VerticalAlignment = Enum.VerticalAlignment.Center
    logoLayout.Parent = logoContainer

    local logoSlot = Instance.new("Frame")
    logoSlot.Name = "LogoSlot"
    logoSlot.Size = UDim2.fromOffset(26, 26)
    logoSlot.BackgroundTransparency = 1
    logoSlot.LayoutOrder, logoSlot.ZIndex = 1, 3
    logoSlot.Parent = logoContainer
    local cr = makeLogo(logoSlot, 26)
    cr.AnchorPoint, cr.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
    do
        local glow = makeLogo(cr, 29)
        glow.Name = "LogoSilverGlow"
        glow.AnchorPoint, glow.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
        glow.ImageColor3, glow.ImageTransparency = Color3.fromRGB(235, 239, 247), 0.15
        glow.ZIndex = cr.ZIndex + 1
        local shine = Instance.new("UIGradient")
        shine.Rotation, shine.Offset = 25, Vector2.new(-1.5, 0)
        shine.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(0.35, 1),
            NumberSequenceKeypoint.new(0.5, 0),
            NumberSequenceKeypoint.new(0.65, 1),
            NumberSequenceKeypoint.new(1, 1)
        })
        shine.Parent = glow
        local spin = TweenService:Create(cr, TweenInfo.new(8, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {Rotation = 360})
        local flash = TweenService:Create(shine, TweenInfo.new(3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, false, 9), {Offset = Vector2.new(1.5, 0)})
        spin:Play()
        flash:Play()
        RegisterUnloadCallback(function() spin:Cancel() flash:Cancel() end)
    end

    do
        local dock = new("Frame", {Name = "PlayerAccountDock", Position = UDim2.fromOffset(16, topBarHeight), Size = UDim2.new(1, -32, 0, 42), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5}, innerClip)
        new("UIListLayout", {FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 9), SortOrder = Enum.SortOrder.LayoutOrder}, dock)
        local badge = bind(new("Frame", {Name = "AccountBadge", Size = UDim2.fromOffset(28, 28), BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = 1, ZIndex = 6}, dock), "BackgroundColor3", function() return COLOR_CONTROL end)
        corner(badge, 99)

        local avatar = new("ViewportFrame", {Name = "PlayerHeadshot", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Ambient = Color3.fromRGB(220, 220, 220), LightColor = WHITE, LightDirection = Vector3.new(-1, -1, -2), ZIndex = 7}, badge)
        corner(avatar, 99)
        local portraitWorld = new("WorldModel", {}, avatar)
        local portraitCamera = new("Camera", {FieldOfView = 32}, avatar)
        avatar.CurrentCamera = portraitCamera
        local portraitGeneration = 0

        local function clonePortraitPart(source)
            local archivable = source.Archivable
            source.Archivable = true
            local ok, copy = pcall(source.Clone, source)
            source.Archivable = archivable
            if not ok or not copy then return end
            for _, object in ipairs(copy:GetDescendants()) do
                if object:IsA("LuaSourceContainer") or object:IsA("JointInstance") or object:IsA("Constraint") then
                    object:Destroy()
                end
            end
            copy.Anchored = true
            copy.CanCollide, copy.CanTouch, copy.CanQuery = false, false, false
            copy.LocalTransparencyModifier = 0
            copy.Transparency = 0
            return copy
        end

        local function updatePortrait(character)
            portraitGeneration += 1
            local token = portraitGeneration
            task.spawn(function()
                local head = character and character:WaitForChild("Head", 10)
                if not head or not head:IsA("BasePart") or token ~= portraitGeneration
                    or LocalPlayer.Character ~= character or not avatar.Parent then return end
                local copy = clonePortraitPart(head)
                if not copy then return end
                portraitWorld:ClearAllChildren()
                copy.CFrame = CFrame.new()
                copy.Parent = portraitWorld
                for _, accessory in ipairs(character:GetChildren()) do
                    if accessory:IsA("Accessory") then
                        local handle = accessory:FindFirstChild("Handle")
                        local weld = handle and handle:FindFirstChild("AccessoryWeld")
                        local attached = weld and (weld.Part0 == head or weld.Part1 == head)
                        if handle and not attached then
                            for _, attachment in ipairs(handle:GetChildren()) do
                                if attachment:IsA("Attachment") and head:FindFirstChild(attachment.Name) then
                                    attached = true
                                    break
                                end
                            end
                        end
                        if handle and handle:IsA("BasePart") and attached then
                            local hair = clonePortraitPart(handle)
                            if hair then
                                hair.CFrame = head.CFrame:ToObjectSpace(handle.CFrame)
                                hair.Parent = portraitWorld
                            end
                        end
                    end
                end
                local distance = math.max(copy.Size.X, copy.Size.Y) * 2.2
                local focus = Vector3.new(0, copy.Size.Y * 0.1, 0)
                portraitCamera.CFrame = CFrame.lookAt(focus + Vector3.new(0, 0, -distance), focus)
            end)
        end
        updatePortrait(LocalPlayer.Character)
        TrackGuiConnection(LocalPlayer.CharacterAdded:Connect(updatePortrait))
        TrackGuiConnection(LocalPlayer.CharacterAppearanceLoaded:Connect(updatePortrait))
        TrackGuiConnection(avatar.Destroying:Connect(function() portraitGeneration += 1 end))

        caption(dock, {Name = "PlayerUsername", Size = UDim2.fromOffset(0, 20), AutomaticSize = Enum.AutomaticSize.X, Text = "@" .. LocalPlayer.Name, TextSize = TS, LayoutOrder = 2, ZIndex = 7})
        local tierColor = IS_PREMIUM_USER and function() return Color3.fromRGB(255, 214, 110) end or accentColor
        local pill = bind(new("Frame", {Name = "TierPill", Size = UDim2.fromOffset(0, 16), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = 3, ZIndex = 6}, dock), "BackgroundColor3", tierColor)
        corner(pill, 5)

        new("UIPadding", {PaddingLeft = UDim.new(0, 7), PaddingRight = UDim.new(0, 7)}, pill)
        local tier = new("TextLabel", {Name = "PrimeSubtitle", BackgroundTransparency = 1, Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, Text = IS_PREMIUM_USER and "Premium" or "Freemium", TextColor3 = WHITE, TextSize = 9, ZIndex = 7}, pill)
        local sh = new("UIGradient", {Offset = Vector2.new(-1, 0), Color = IS_PREMIUM_USER and ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 145, 35)),
            ColorSequenceKeypoint.new(0.35, Color3.fromRGB(255, 230, 142)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 248, 211)),
            ColorSequenceKeypoint.new(0.65, Color3.fromRGB(255, 230, 142)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(210, 145, 35))
        }) or ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(157, 195, 255)),
            ColorSequenceKeypoint.new(0.2, Color3.fromRGB(194, 169, 255)),
            ColorSequenceKeypoint.new(0.4, Color3.fromRGB(255, 192, 230)),
            ColorSequenceKeypoint.new(0.6, Color3.fromRGB(236, 247, 255)),
            ColorSequenceKeypoint.new(0.8, Color3.fromRGB(165, 232, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(157, 195, 255))
        })}, tier)
        local tierShine = TweenService:Create(sh, TweenInfo.new(2.6, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {Offset = Vector2.new(1, 0)})
        tierShine:Play()
        TrackGuiConnection(screenGui.Destroying:Connect(function() tierShine:Cancel() end))
    end

    local tabStrip = Instance.new("ScrollingFrame")
    tabStrip.Name = "TabStrip"
    tabStrip.Size = UDim2.new(1, -142, 1, 0)
    tabStrip.Position = UDim2.new(0, 50, 0, 0)
    tabStrip.BackgroundTransparency = 1
    tabStrip.ClipsDescendants = true
    tabStrip.ZIndex = 3
    tabStrip.Active = true
    tabStrip.Parent = topBar

    do
        tabStrip.BorderSizePixel = 0
        tabStrip.CanvasSize = UDim2.fromScale(0, 1)
        tabStrip.AutomaticCanvasSize = Enum.AutomaticSize.X
        tabStrip.ScrollingDirection = Enum.ScrollingDirection.X
        tabStrip.ScrollBarThickness = 3
        NexusUI:BindColor(tabStrip, "ScrollBarImageColor3", function() return COLOR_BORDER end)
        tabStrip.ScrollBarImageTransparency = 0.2
        tabStrip.ElasticBehavior = Enum.ElasticBehavior.Never

        local function updateMobileTabStripBounds()
            if not tabStrip or not tabStrip.Parent then return end
            local measuredLogoWidth = math.floor(logoContainer.AbsoluteSize.X / math.max(fit.Scale, 0.1) + 0.5)
            local leftInset = math.max(50, measuredLogoWidth + 26)
            local rightInset = 92
            tabStrip.Position = UDim2.new(0, leftInset, 0, 0)
            tabStrip.Size = UDim2.new(1, -(leftInset + rightInset), 1, 0)
        end

        TrackGuiConnection(logoContainer:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateMobileTabStripBounds))
        task.defer(updateMobileTabStripBounds)
    end

    local tabStripLayout = Instance.new("UIListLayout")
    tabStripLayout.FillDirection = Enum.FillDirection.Horizontal
    tabStripLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
    tabStripLayout.VerticalAlignment = Enum.VerticalAlignment.Center
    tabStripLayout.Padding = UDim.new(0, 2)
    tabStripLayout.SortOrder = Enum.SortOrder.LayoutOrder
    tabStripLayout.Parent = tabStrip

    local mobileTabHintHeight = 0

    local window = {}
    --[=[
    local snowfall = createSnowfall(mainFrame, innerClip, screenGui)
    function window:SetAutumnLeavesEnabled(value)
        snowfall.SetEnabled(value == true)
    end
    RegisterUnloadCallback(snowfall.Destroy)
    ]=]
    local restoreGui
    local connections = {}
    local function track(conn)
        if conn then
            table.insert(connections, conn)
        end
        return conn
    end

    local mobileRestoreFrame, mobileFoldTween
    local savedCompactPosition
    local compactSize = IS_MOBILE and UDim2.fromOffset(64, 34) or UDim2.fromOffset(260, 46)
    local compactStats = {}
    local compactValues = {FPS = "--", PING = "--", TIME = "--:--:--"}
    local function updateCompactStats()
        for key, label in pairs(compactStats) do
            if label.Parent then label.Text = compactValues[key] end
        end
    end

    local function compactPosition(position)
        local bounds = restoreGui.AbsoluteSize
        if bounds.X <= 0 or bounds.Y <= 0 then return position end
        return UDim2.fromOffset(
            math.clamp(position.X.Scale * bounds.X + position.X.Offset, 0, math.max(0, bounds.X - compactSize.X.Offset)),
            math.clamp(position.Y.Scale * bounds.Y + position.Y.Offset, 0, math.max(0, bounds.Y - compactSize.Y.Offset))
        )
    end

    local function createRestoreGui()
        if not SHOW_RESTORE_BUTTON and not useCompactRestore then
            return nil
        end

        if restoreGui then
            return restoreGui
        end

        restoreGui = Instance.new("ScreenGui")
        restoreGui.Name = "NexusMarvelOmegaUI_Restore"
        restoreGui.ResetOnSpawn = false
        restoreGui.IgnoreGuiInset = true
        if useCompactRestore then
            pcall(function()
                restoreGui.ScreenInsets = Enum.ScreenInsets.None
                restoreGui.ClipToDeviceSafeArea = false
            end)
            restoreGui.DisplayOrder = screenGui.DisplayOrder + 1
        end
        restoreGui.Enabled = false
        restoreGui.Parent = GuiParent

        local restoreFrame = Instance.new("Frame")
        restoreFrame.Size = UDim2.fromOffset(48, 48)
        restoreFrame.AnchorPoint = Vector2.new(0.5, 0.5)
        restoreFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
        restoreFrame.BorderSizePixel = 0
        restoreFrame.BackgroundTransparency = 1
        restoreFrame.Parent = restoreGui
        restoreFrame.Active = true

        local restoreButton
        if useCompactRestore then
            mobileRestoreFrame = restoreFrame
            restoreFrame.Name = "CompactWindow"
            restoreFrame.Size = compactSize
            restoreFrame.AnchorPoint = Vector2.zero
            restoreFrame.Position = UDim2.fromOffset(16, 48)
            restoreFrame.BackgroundColor3 = mainFrame.BackgroundColor3
            restoreFrame.BackgroundTransparency = mainFrame.BackgroundTransparency
            restoreFrame.ClipsDescendants = true
            windowGradient().Parent = restoreFrame
            local compactCorner = mainCorner:Clone()
            if not IS_MOBILE then compactCorner.CornerRadius = UDim.new(0, 3) end
            compactCorner.Parent = restoreFrame
            do
                local stroke = mainStroke:Clone()
                local gradient = stroke:FindFirstChildOfClass("UIGradient")
                if gradient then gradient:Destroy() end
                borderGradient().Parent = stroke
                stroke.Parent = restoreFrame
            end
            local artwork = createImageBackground(restoreFrame)
            if not IS_MOBILE then
                local artworkCorner = artwork:FindFirstChildOfClass("UICorner")
                if artworkCorner then artworkCorner.CornerRadius = UDim.new(0, 3) end
            end

