    local function cancelMobileFold()
        if not mobileFoldTween then return end
        local tween = mobileFoldTween
        mobileFoldTween = nil
        tween:Cancel()
    end

    local function setMobileVisible(visible)
        local wasVisible = mainFrame.Visible and screenGui.Enabled
        local gui = createRestoreGui()
        local frame = mobileRestoreFrame
        if not gui or not frame then return end
        if visible then
            cancelMobileFold()
            local windowScale = mainFrame:FindFirstChild("NexusWindowScale")
            if windowScale then windowScale.Scale = targetScale end
            mainFrame.BackgroundTransparency = MAIN_WINDOW_TRANSPARENCY
            screenGui.Enabled = true
            mainFrame.Visible = true
            gui.Enabled = false
            frame.Size = compactSize
            if savedCompactPosition then frame.Position = compactPosition(savedCompactPosition) end
            return
        end
        if not wasVisible and mobileFoldTween == nil then
            if savedCompactPosition then frame.Position = compactPosition(savedCompactPosition) end
            gui.Enabled = true
            return
        end

        cancelMobileFold()
        local origin = mainFrame.AbsolutePosition - gui.AbsolutePosition
        local fullPosition = UDim2.fromOffset(origin.X, origin.Y)
        local smallPosition = compactPosition(savedCompactPosition or fullPosition)
        savedCompactPosition = smallPosition
        frame.Position = fullPosition
        frame.Size = UDim2.fromOffset(mainFrame.AbsoluteSize.X, mainFrame.AbsoluteSize.Y)
        gui.Enabled = true
        mainFrame.Visible = false

        local tween = TweenService:Create(frame, TweenInfo.new(0.24, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
            Size = compactSize,
            Position = smallPosition,
        })
        mobileFoldTween = tween
        tween.Completed:Once(function()
            if mobileFoldTween == tween then mobileFoldTween = nil end
        end)
        tween:Play()
    end

    setVisible = function(visible)
        if useCompactRestore then
            setMobileVisible(visible)
            return
        end
        if visible then
            mainFrame.Visible = true
            animateWindowIn()
            if restoreGui then
                restoreGui.Enabled = false
            end
        else
            animateWindowOut(function()
                if mainFrame then
                    mainFrame.Visible = false
                end
            end)
            local mobileButtonGui = createRestoreGui()
            if mobileButtonGui then
                mobileButtonGui.Enabled = true
            end
        end
    end

    local isCollapsed = false

    local function setCollapsed(value)
        isCollapsed = value
        setVisible(not value)
    end

    local dragging = false
    local dragInput = nil
    local dragStartPos = nil
    local dragStartMousePos = nil

    local function isInputInside(guiObject, inputPosition)
        if not guiObject or not guiObject.Parent then return false end
        local pos = guiObject.AbsolutePosition
        local size = guiObject.AbsoluteSize
        local x = inputPosition.X
        local y = inputPosition.Y
        return x >= pos.X and x <= (pos.X + size.X) and y >= pos.Y and y <= (pos.Y + size.Y)
    end

    local function visibleAt(object, position)
        if not isInputInside(object, position) then return false end
        local parent = object
        while parent and parent ~= screenGui do
            if parent:IsA("GuiObject") then
                if not parent.Visible then return false end
                if parent.ClipsDescendants and not isInputInside(parent, position) then return false end
            end
            parent = parent.Parent
        end
        return parent == screenGui
    end
    local function blockedDrag(position)
        for _, object in ipairs(mainFrame:GetDescendants()) do
            if object:IsA("GuiObject") and visibleAt(object, position) then
                if object:IsA("GuiButton") or object:IsA("TextBox") or object:GetAttribute("BlockWindowDrag") then return true end
                if object:IsA("ScrollingFrame") and object.ScrollingEnabled and object.ScrollBarThickness > 0 then
                    local edge = object.AbsolutePosition + object.AbsoluteSize
                    local width = object.ScrollBarThickness + 5
                    if object.AbsoluteCanvasSize.Y > object.AbsoluteWindowSize.Y and position.X >= edge.X - width then return true end
                    if object.AbsoluteCanvasSize.X > object.AbsoluteWindowSize.X and position.Y >= edge.Y - width then return true end
                end
            end
        end
        return false
    end
    track(userInputService.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
        if dragging or not screenGui.Enabled or not mainFrame.Visible or userInputService:GetFocusedTextBox() then return end
        if not isInputInside(mainFrame, input.Position) or blockedDrag(input.Position) then return end
        dragging, dragInput = true, input
        dragStartPos, dragStartMousePos = mainFrame.Position, input.Position
    end))

    track(userInputService.InputChanged:Connect(function(input)
        if dragging and (input == dragInput or dragInput.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement) then
            if dragStartPos and dragStartMousePos then
                local delta = input.Position - dragStartMousePos
                mainFrame.Position = UDim2.new(
                    dragStartPos.X.Scale,
                    dragStartPos.X.Offset + delta.X,
                    dragStartPos.Y.Scale,
                    dragStartPos.Y.Offset + delta.Y
                )
            end
        end
    end))

    track(userInputService.InputEnded:Connect(function(input)
        if input == dragInput or dragInput and dragInput.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging, dragInput = false, nil
        end
    end))
    track(userInputService.WindowFocusReleased:Connect(function() dragging, dragInput = false, nil end))

    local footer = 28
    local content = new("Frame", {Size = UDim2.new(1, -32, 1, -(topBarHeight + 54 + footer + mobileTabHintHeight)), Position = UDim2.fromOffset(16, topBarHeight + 42 + mobileTabHintHeight), BackgroundTransparency = 1, ZIndex = 3, ClipsDescendants = true}, innerClip)
    local cornerButtons = new("Frame", {Name = "CornerButtons", Size = UDim2.fromOffset(58, 24), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -10, 0.5, 0), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 8}, topBar)
    new("UIListLayout", {FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder}, cornerButtons)
    local statsFrame = new("Frame", {Name = "PerformanceStats", Size = UDim2.new(1, 0, 0, footer), Position = UDim2.new(0, 0, 1, -footer), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 6}, innerClip)
    bind(new("Frame", {Size = UDim2.new(1, 0, 0, 1), Position = UDim2.new(0, 0, 1, -footer), BackgroundTransparency = 0.93, BorderSizePixel = 0, ZIndex = 6}, innerClip), "BackgroundColor3", textColor)
    new("UIListLayout", {FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder}, statsFrame)
    new("UIPadding", {PaddingLeft = UDim.new(0, 18)}, statsFrame)
    local function stat(title, order)
        local dot = new("Frame", {Size = UDim2.fromOffset(5, 5), BackgroundColor3 = GOOD, BorderSizePixel = 0, LayoutOrder = order, ZIndex = 7}, statsFrame)
        corner(dot, 99)
        local glow = icon("glow", 15, 15, GOOD, dot)
        caption(statsFrame, {Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, Text = title, TextSize = 11, LayoutOrder = order + 1, ZIndex = 7}, dimText)
        local value = caption(statsFrame, {Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, Text = "--", FontFace = TEXT_FONT, TextSize = 11, LayoutOrder = order + 2, ZIndex = 7})
        new("Frame", {Size = UDim2.fromOffset(6, 1), BackgroundTransparency = 1, LayoutOrder = order + 3}, statsFrame)
        return function(shown, color) value.Text, dot.BackgroundColor3, glow.ImageColor3 = shown, color, color end
    end
    local setFps, setPing = stat("FPS", 1), stat("PING", 5)
    local frames, sampleTime = 0, 0
    track(RunService.RenderStepped:Connect(function(dt)
        frames += 1
        sampleTime += dt
        if sampleTime < 0.5 then return end
        local fps, ping = math.floor(frames / sampleTime + 0.5), 0
        pcall(function() ping = math.floor(LocalPlayer:GetNetworkPing() * 1000 + 0.5) end)
        setFps(tostring(fps), ACCENT)
        setPing(ping .. " MS", ACCENT)
        compactValues.FPS, compactValues.PING = tostring(fps), tostring(ping)
        if not IS_MOBILE then
            local ok, localTime = pcall(function() return DateTime.now():FormatLocalTime("HH:mm:ss", "en-us") end)
            if ok then compactValues.TIME = localTime end
            updateCompactStats()
        end
        frames, sampleTime = 0, 0
    end))

    if IS_MOBILE then
        local resizeHandle = Instance.new("TextButton")
        resizeHandle.Name = "ResizeHandle"
        resizeHandle.Size = UDim2.fromOffset(24, 24)
        resizeHandle.Position = UDim2.new(1, -24, 1, -24)
        resizeHandle.BackgroundTransparency = 1
        resizeHandle.BorderSizePixel = 0
        resizeHandle.Text = "◢"
        NexusUI:BindColor(resizeHandle, "TextColor3", function() return ACCENT end)
        resizeHandle.Font = Enum.Font.GothamBold
        resizeHandle.TextSize = 15
        resizeHandle.AutoButtonColor = false
        resizeHandle.ZIndex = 20
        resizeHandle.Parent = innerClip

        local resizing, resizeStart, resizeSize = false, nil, nil
        track(resizeHandle.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            resizing = true
            resizeStart = input.Position
            resizeSize = mainFrame.AbsoluteSize / math.max(fit.Scale, 0.1)
        end))
        track(userInputService.InputChanged:Connect(function(input)
            if not resizing or not resizeStart or not resizeSize then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local camera = Workspace.CurrentCamera
            if not camera then return end
            local delta = (input.Position - resizeStart) / math.max(fit.Scale, 0.1)
            local minWidth = IS_MOBILE and 320 or 430
            local minHeight = 320
            local maxWidth = math.max(minWidth, (camera.ViewportSize.X - mainFrame.AbsolutePosition.X - 8) / math.max(fit.Scale, 0.1))
            local maxHeight = math.max(minHeight, (camera.ViewportSize.Y - mainFrame.AbsolutePosition.Y - 48) / math.max(fit.Scale, 0.1))
            preferredSize = Vector2.new(
                math.clamp(math.floor(resizeSize.X + delta.X + 0.5), minWidth, maxWidth),
                math.clamp(math.floor(resizeSize.Y + delta.Y + 0.5), minHeight, maxHeight)
            )
            userResized = true
            mainFrame.Size = UDim2.fromOffset(preferredSize.X, preferredSize.Y)
        end))
        track(userInputService.InputEnded:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            if resizing then
                resizing = false
                fitWindow()
            end
        end))
    end

    local function createCornerButton(name, fallback, order)
        local btn = bind(new("TextButton", {Size = UDim2.fromOffset(26, 24), BackgroundTransparency = 0.945, BorderSizePixel = 0, Text = atlas and "" or fallback, TextSize = TS, AutoButtonColor = false, LayoutOrder = order, ZIndex = 9}, cornerButtons), "BackgroundColor3", textColor)
        bind(btn, "TextColor3", textColor)
        corner(btn, 7)
        stroke(btn, 0.92)
        icon(name, 12, 12, textColor, btn).ZIndex = 9
        TrackGuiConnection(btn.MouseEnter:Connect(function() TweenService:Create(btn, TweenInfo.new(0.1, Enum.EasingStyle.Quad), {BackgroundTransparency = 0.87}):Play() end))
        TrackGuiConnection(btn.MouseLeave:Connect(function() TweenService:Create(btn, TweenInfo.new(0.1, Enum.EasingStyle.Quad), {BackgroundTransparency = 0.945}):Play() end))
        return btn
    end
    local hideCornerButton = createCornerButton("minus", "-", 1)
    ConnectClick(hideCornerButton, function() setVisible(false) end)
    local closeCornerButton = createCornerButton("close", "X", 2)
    ConnectClick(closeCornerButton, function() createCloseConfirm() end)

    local tabs = {}
    local currentTab = nil

    local tabTextService = game:GetService("TextService")
    local tabTextSize = 12.7
    local function measureTab(button)
        local text = button.Text
        button.Size = UDim2.new(0, (utf8.len(text) or #text) * tabTextSize + 12, 1, -8)
        task.defer(function()
            if not button.Parent then return end
            local ok, bounds = pcall(function()
                local params = Instance.new("GetTextBoundsParams")
                params.Text, params.Font, params.Size, params.Width = text, TEXT_FONT, tabTextSize, 10000
                return tabTextService:GetTextBoundsAsync(params)
            end)
            if ok and bounds.X > 0 and button.Parent and button.Text == text then
                button.Size = UDim2.new(0, math.ceil(bounds.X) + 12, 1, -8)
            end
        end)
    end

    local function selectTab(index)
        local tabEntry = tabs[index]
        if not tabEntry then return end
        if currentTab == tabEntry then return end
        for i, tab in ipairs(tabs) do
            local selected = (i == index)
            tab.underline.Visible = selected
            bind(tab.button, "TextColor3", selected and textColor or dimColor)
            tab.page.Visible = selected
            tab.page.GroupTransparency = 0
            tab.page.Position = UDim2.fromOffset(0,0)
        end
        currentTab = tabEntry
    end

    local toggleKey = options and options.MinimizeKey or Enum.KeyCode.LeftAlt
    local toggleKeyName = "LeftAlt"

    local function updateToggleKeyDisplay()
        if toggleKey and toggleKey.Name then
            toggleKeyName = toggleKey.Name
        end
    end

    updateToggleKeyDisplay()

    function window:SetToggleKey(key)
        toggleKey = key or Enum.KeyCode.LeftAlt
        updateToggleKeyDisplay()
    end

    function window:GetToggleKey()
        return toggleKey
    end

    local function featureArtwork() return nil, false end
    local function decorateFeature(frame, id, data, kind)
        local image, card = featureArtwork(id, data.Title)
        if not image or not frame or not frame:IsA("GuiObject") or frame:GetAttribute("FeatureArtwork") then return end
        local label
        for _, child in ipairs(frame:GetChildren()) do
            if child:IsA("TextLabel") and string.lower(child.Text) == string.lower(tostring(data.Title or id)) then label = child; break end
        end
        if not label then return end
        frame:SetAttribute("FeatureArtwork", true)
        local size = kind == "AddToggle" and (IS_MOBILE and 22 or 18) or 14
        local gap = size + 7
        local position = label.Position
        local top = kind == "AddDropdown" and UDim2.new(position.X.Scale, position.X.Offset, 0, position.Y.Offset + 7)
            or UDim2.new(position.X.Scale, position.X.Offset, 0, (IS_MOBILE and 44 or 32) * 0.5)
        if kind == "AddSlider" or kind == "AddButton" then top = UDim2.new(position.X.Scale, position.X.Offset, 0.5, 0) end
        local artwork = new("ImageLabel", {Name = "GameFeatureIcon", Image = image, Size = UDim2.fromOffset(size, size), AnchorPoint = Vector2.new(0, 0.5), Position = top, BackgroundTransparency = 1, BorderSizePixel = 0, ScaleType = card and Enum.ScaleType.Crop or Enum.ScaleType.Fit, ImageTransparency = 0.04, Active = false, ZIndex = 3}, frame)
        if card then corner(artwork, 4) end
        label.Size = UDim2.new(label.Size.X.Scale, label.Size.X.Offset - gap, label.Size.Y.Scale, label.Size.Y.Offset)
        label.Position = UDim2.new(position.X.Scale, position.X.Offset + gap, position.Y.Scale, position.Y.Offset)
    end


    function window:AddTab(tabData)
        local tabButton = new("TextButton", {BackgroundTransparency = 1, Text = string.upper(tostring(tabData and tabData.Title or "Tab")), AutoButtonColor = false, LayoutOrder = #tabs + 1, ZIndex = 4})
        tabButton:SetAttribute("KeepFont", true)
        tabButton.FontFace, tabButton.TextSize = TEXT_FONT, tabTextSize
        bind(tabButton, "TextColor3", dimColor)
        tabButton.Parent = tabStrip
        local tabUnderline = new("Frame", {Name = "ActiveTabUnderline", Size = UDim2.new(1, -12, 0, 2), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 1, -5), BackgroundColor3 = WHITE, BackgroundTransparency = 0.12, BorderSizePixel = 0, Visible = false, ZIndex = 4}, tabButton)
        corner(tabUnderline, 99)
        local tabGlow = new("Frame", {Name = "ActiveTabGlow", Size = UDim2.new(1, 8, 0, 6), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), BackgroundColor3 = WHITE, BackgroundTransparency = 0.8, BorderSizePixel = 0, Active = false, ZIndex = 3}, tabUnderline)
        corner(tabGlow, 99)
        new("UIGradient", {Rotation = 90, Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.4), NumberSequenceKeypoint.new(1, 1)})}, tabGlow)
        if tabData and tabData.Badge then
            new("TextLabel", {Name = "TabBadge", Size = UDim2.fromOffset(24, 8), Position = UDim2.new(1, -24, 0, 0), BackgroundTransparency = 1, Text = tostring(tabData.Badge), TextColor3 = GOOD, FontFace = TEXT_FONT, TextSize = 7, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 5}, tabButton)
        end
        TrackGuiConnection(tabButton.MouseEnter:Connect(function() if not tabUnderline.Visible then bind(tabButton, "TextColor3", textColor) end end))
        TrackGuiConnection(tabButton.MouseLeave:Connect(function() if not tabUnderline.Visible then bind(tabButton, "TextColor3", dimColor) end end))

        local tabPage = Instance.new("CanvasGroup")
        tabPage.Size = UDim2.new(1, 0, 1, 0)
        tabPage.Position = UDim2.new(0, 0, 0, 0)
        tabPage.BackgroundTransparency = 1
        tabPage.GroupTransparency = 1
        tabPage.Visible = false
        tabPage.ClipsDescendants = true
        tabPage.Parent = content

        local function createColumn(position)
            local column = bind(new("ScrollingFrame", {Size = UDim2.new(0.5, -6, 1, 0), Position = position, BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3, ScrollBarImageTransparency = 0.3, VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar, AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new()}, tabPage), "ScrollBarImageColor3", function() return COLOR_BORDER end)
            new("UIListLayout", {Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder}, column)
            new("UIPadding", {PaddingLeft = UDim.new(0, 1), PaddingRight = UDim.new(0, 1), PaddingTop = UDim.new(0, 1), PaddingBottom = UDim.new(0, 1)}, column)
            return column
        end

        local leftColumn = createColumn(UDim2.new())
        local rightColumn = createColumn(UDim2.new(0.5, 6, 0, 0))
        local arranging = false
        local function arrangeColumns()
            if arranging then return end
            arranging = true
            local narrow = mainFrame.Size.X.Offset < 540
            leftColumn.Size = UDim2.new(narrow and 1 or 0.5, narrow and 0 or -6, 1, 0)
            rightColumn.Visible = not narrow
            for i,column in ipairs({leftColumn,rightColumn}) do
                for _,o in ipairs(column:GetChildren()) do
                    if o:IsA("GuiObject") then
                        local home = o:GetAttribute("ColumnHome") or i
                        o:SetAttribute("ColumnHome", home)
                        o.Parent = (narrow or home == 1) and leftColumn or rightColumn
                    end
                end
            end
            arranging = false
        end
        TrackGuiConnection(leftColumn.ChildAdded:Connect(arrangeColumns))
        TrackGuiConnection(rightColumn.ChildAdded:Connect(arrangeColumns))
        TrackGuiConnection(mainFrame:GetPropertyChangedSignal("Size"):Connect(arrangeColumns))
        arrangeColumns()


        local tabObject = {}
        local controls = {}
        local sectionCount = 0
        local currentSectionContent = nil
        tabObject.Page = tabPage
        tabObject.Button = tabButton

        local accents, lastKind = {}, {}
        local function divider(parent, kind)
            local last = lastKind[parent]
            lastKind[parent] = kind
            if not last or kind == "sub" or kind == "button" or last == "button" then return end
            table.insert(controls, bind(new("Frame", {Name = "Line", Size = UDim2.new(1, 0, 0, 1), BackgroundTransparency = 0.955, BorderSizePixel = 0, LayoutOrder = #controls + 1}, parent), "BackgroundColor3", textColor))
        end
        local function createSection(title, side, order)
            title = tostring(title)
            local accent = accentColor
            local group = bind(new("Frame", {Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 0.64, BorderSizePixel = 0, LayoutOrder = order}), "BackgroundColor3", function() return Color3.fromRGB(9, 9, 12) end)
            group:SetAttribute("ColumnHome", side)
            corner(group, 9)
            stroke(group, 0.915)
            new("UIListLayout", {SortOrder = Enum.SortOrder.LayoutOrder}, group)
            if title ~= "" then
                local header = new("Frame", {Size = UDim2.new(1, 0, 0, 32), BackgroundTransparency = 1, ClipsDescendants = true, LayoutOrder = 0, ZIndex = 2}, group)
                local tick = bind(new("Frame", {Size = UDim2.fromOffset(3, 10), Position = UDim2.new(0, 12, 0.5, -5), BorderSizePixel = 0, ZIndex = 3}, header), "BackgroundColor3", accent)
                corner(tick, 2)
                icon("glow", 15, 22, accent, tick).ImageTransparency = 0.35
                caption(header, {Size = UDim2.new(1, -35, 1, 0), Position = UDim2.fromOffset(23, 0), Text = string.upper(title), TextSize = 11, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 3}, dimColor)
                bind(new("Frame", {Size = UDim2.new(1, 0, 0, 1), Position = UDim2.new(0, 0, 1, -1), BackgroundTransparency = 0.93, BorderSizePixel = 0, ZIndex = 3}, header), "BackgroundColor3", textColor)
            end
            local sectionContent = new("Frame", {Name = "Content", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = 1}, group)
            new("UIListLayout", {SortOrder = Enum.SortOrder.LayoutOrder}, sectionContent)
            new("UIPadding", {PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12), PaddingBottom = UDim.new(0, 3)}, sectionContent)
            accents[sectionContent] = accent
            group.Parent = side == 1 and leftColumn or rightColumn
            return {Frame = group, Content = sectionContent}
        end

        function tabObject:AddSection(title, column)
            sectionCount = sectionCount + 1
            local sectionObject = createSection(title, column == "Right" and 2 or column == "Left" and 1 or (sectionCount % 2 == 1 and 1 or 2), sectionCount)
            currentSectionContent = sectionObject.Content
            return sectionObject
        end

        function tabObject:SetActiveSection(sectionObject)
            if sectionObject and sectionObject.Content then
                currentSectionContent = sectionObject.Content
                return true
            end
            return false
        end

        local function getControlParent()
            if not currentSectionContent then currentSectionContent = createSection("", 1, 0).Content end
            return currentSectionContent
        end

        function tabObject:AddToggle(id, data)
            local parent = getControlParent()
            local accent = accents[parent] or accentColor
            divider(parent, "toggle")
            local rowHeight = IS_MOBILE and 44 or 32
            local showDescription = data and data.ShowDescription == true
            local SWITCH_W = IS_MOBILE and 22 or 18
            local SWITCH_H = SWITCH_W
            local toggleFrame = new("Frame", {Size = UDim2.new(1, 0, 0, rowHeight), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Active = true, LayoutOrder = #controls + 1, BorderSizePixel = 0}, parent)
            toggleFrame:SetAttribute("BlockWindowDrag", true)
            local label = caption(toggleFrame, {Size = UDim2.new(1, -(SWITCH_W + 12), 0, showDescription and 27 or 0), AutomaticSize = showDescription and Enum.AutomaticSize.None or Enum.AutomaticSize.Y, Text = data and data.Title or id, TextSize = TS, TextWrapped = not showDescription, TextTruncate = showDescription and Enum.TextTruncate.AtEnd or Enum.TextTruncate.None})
            local descriptionLabel
            if showDescription then
                local warn = data.DescriptionColor ~= nil
                descriptionLabel = caption(toggleFrame, {Name = "Description", Size = UDim2.new(1, -(SWITCH_W + (warn and 28 or 12)), 0, 0), Position = UDim2.fromOffset(warn and 16 or 0, 25), AutomaticSize = Enum.AutomaticSize.Y, Text = tostring(data.Description or ""), TextWrapped = true, TextSize = 9, TextYAlignment = Enum.TextYAlignment.Top}, function() return data.DescriptionColor or COLOR_TEXT_DIM end)
                new("UIPadding", {PaddingBottom = UDim.new(0, 9)}, descriptionLabel)
                if warn then icon("warn", 11, 11, function() return data.DescriptionColor end, toggleFrame).Position = UDim2.fromOffset(6, 30) end
            else
                new("UIPadding", {PaddingTop = UDim.new(0, math.floor((rowHeight - TS) / 2)), PaddingBottom = UDim.new(0, math.ceil((rowHeight - TS) / 2))}, label)
            end
            local lockedBanner = caption(toggleFrame, {Name = "LockedBanner", Size = UDim2.fromScale(1, 1), Text = data and data.LockedText or "", TextSize = 10, TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.AtEnd, Visible = false, ZIndex = 3}, dimColor)
            local switch = new("Frame", {Name = "Checkbox", AnchorPoint = Vector2.new(1, 0.5), Size = UDim2.fromOffset(SWITCH_W, SWITCH_H), Position = UDim2.new(1, -1, 0, rowHeight * 0.5), BackgroundTransparency = 1, BorderSizePixel = 0, Active = false}, toggleFrame)
            corner(switch, IS_MOBILE and 5 or 4)
            local switchStroke = stroke(switch, 0.55)
            local checkmark = new("Frame", {Name = "Checkmark", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Active = false, ZIndex = 3}, switch)
            local checkScale = new("UIScale", {Scale = 1}, checkmark)
            checkmark.AnchorPoint, checkmark.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
            local function checkSegment(name, x, y, length, rotation)
                local segment = new("Frame", {Name = name, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromScale(length, 0.12), Position = UDim2.fromScale(x, y), Rotation = rotation, BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0, Active = false, ZIndex = 4}, checkmark)
                corner(segment, 99)
                return segment
            end
            local checkShort = checkSegment("CheckShort", 0.32, 0.54, 0.28, 45)
            local checkLong = checkSegment("CheckLong", 0.58, 0.46, 0.48, -45)
            local checkProgress = new("NumberValue", {Name = "CheckProgress", Value = 0}, checkmark)
            local function drawCheck()
                local progress = math.clamp(checkProgress.Value, 0, 1)
                checkShort.BackgroundTransparency = 1 - progress
                checkLong.BackgroundTransparency = 1 - progress
                checkScale.Scale = 0.86 + progress * 0.14
                checkmark.Visible = progress > 0.001
            end
            TrackGuiConnection(checkProgress:GetPropertyChangedSignal("Value"):Connect(drawCheck))
            drawCheck()

            local enabled = data and data.Default == true or false
            local locked = false
            local toggleOption = {
                Value = enabled,
                IsToggle = true,
                Locked = false,
                Frame = toggleFrame,
                Label = label,
                Title = data and data.Title or id
            }

            local switchTweens = {}
            local function setSwitch(object, props, animated, duration, easing)
                if switchTweens[object] then switchTweens[object]:Cancel() end
                if animated then
                    switchTweens[object] = TweenService:Create(object, TweenInfo.new(duration or 0.18, easing or Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props)
                    switchTweens[object]:Play()
                else
                    for key, value in pairs(props) do object[key] = value end
                end
            end

            local function refresh(animated)
                local on = enabled and not locked
                setSwitch(switch, {BackgroundColor3 = Color3.fromRGB(45, 47, 52), BackgroundTransparency = 0}, false)
                setSwitch(checkProgress, {Value = on and 1 or 0}, animated, on and 0.22 or 0.18, Enum.EasingStyle.Sine)
                if not animated then drawCheck() end
                setSwitch(switchStroke, {Color = Color3.fromRGB(88, 92, 100), Transparency = locked and 0.85 or 0.45}, false)
                bind(label, "TextColor3", locked and dimColor or textColor)
                lockedBanner.Visible = locked and lockedBanner.Text ~= ""
                label.Visible = not lockedBanner.Visible
                switch.Visible = not lockedBanner.Visible
            end
            refresh(false)
            TrackGuiConnection(toggleFrame.Destroying:Connect(function()
                for _, tween in pairs(switchTweens) do tween:Cancel() end
            end))
            table.insert(NexusUI.ThemeRefresh, function() if toggleFrame.Parent then refresh(false) end end)

            function toggleOption:SetValue(value)
                local newValue = value == true
                if locked and newValue then
                    return false
                end
                if enabled == newValue then
                    return true
                end

                enabled = newValue
                self.Value = enabled
                refresh(true)

                if data and data.Callback then
                    local ok = pcall(data.Callback, enabled)
                    if not ok then
                        enabled = not newValue
                        self.Value = enabled
                        pcall(data.Callback, enabled)
                        refresh(false)
                        return false
                    end
                end
                return true
            end

            function toggleOption:SetTitle(text)
                local newTitle = tostring(text or "")
                -- Drop any bracketed suffix such as a "[LOCK 03:59:59]" countdown.
                newTitle = newTitle:gsub("%s*%[.-%]%s*$", "")
                if newTitle == "" then
                    newTitle = tostring(id)
                end
                self.Title = newTitle
                label.Text = newTitle
            end

            function toggleOption:SetDescription(text)
                local description = tostring(text or "")
                if descriptionLabel then descriptionLabel.Text = description end
                if description ~= "" then
                    label.Text = self.Title or (data and data.Title or id)
                end
            end

            -- Locking is disabled: toggles always stay usable. Kept as no-ops so
            -- external callers (e.g. the loader) do not error.
            function toggleOption:SetLocked(value) end

            function toggleOption:SetLockedText(text) end

            function toggleOption:IsLocked()
                return locked
            end

            NexusUI.Options[id] = toggleOption
            NexusUI.Toggles[id] = toggleOption

            -- A full-row TextButton is a native click/touch target: works with mouse on PC
            -- and tap on phones (Activated fires for both).
            local rowHitbox = Instance.new("TextButton")
            rowHitbox.Name = "TouchHitbox"
            rowHitbox.Size = UDim2.fromScale(1, 1)
            rowHitbox.Position = UDim2.fromScale(0, 0)
            rowHitbox.BackgroundTransparency = 1
            rowHitbox.BorderSizePixel = 0
            rowHitbox.Text = ""
            rowHitbox.AutoButtonColor = false
            rowHitbox.Active = true
            rowHitbox.Selectable = IS_MOBILE
            rowHitbox.ZIndex = 5
            rowHitbox.Parent = toggleFrame
            TrackGuiConnection(rowHitbox.Activated:Connect(function()
                toggleOption:SetValue(not enabled)
            end))

            table.insert(controls, toggleFrame)
            return toggleFrame
        end

        function tabObject:AddSlider(id, data)
            local parent = getControlParent()
            local accent = accents[parent] or accentColor
            local sub = lastKind[parent] == "toggle" or lastKind[parent] == "sub"
            local inset = sub and 19 or 0
            divider(parent, sub and "sub" or "slider")
            local frame = new("Frame", {Size = UDim2.new(1, 0, 0, IS_MOBILE and 34 or 30), BackgroundTransparency = 1, LayoutOrder = #controls + 1, BorderSizePixel = 0}, parent)
            frame:SetAttribute("BlockWindowDrag", true)
            if sub then
                local elbow = icon("elbow", 8, 20, textColor, frame)
                elbow.Position, elbow.ImageTransparency = UDim2.fromOffset(9, 5), 0.78
            end
            local label = caption(frame, {Size = UDim2.new(0.6, -inset, 1, 0), Position = UDim2.fromOffset(inset, 0), Text = data and data.Title or id, TextSize = TS - 2, TextTruncate = Enum.TextTruncate.AtEnd}, dimColor)
            local valueBox = bind(new("Frame", {AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(34, 17), BackgroundTransparency = 0.935, BorderSizePixel = 0}, frame), "BackgroundColor3", textColor)
            corner(valueBox, 5)
            stroke(valueBox, 0.9)
            local valueLabel = caption(valueBox, {Size = UDim2.fromScale(1, 1), Text = tostring(data and data.Default or 0), FontFace = TEXT_FONT, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Center})
            local track = bind(new("Frame", {AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 0.89, BorderSizePixel = 0, ZIndex = 5, Active = true}, frame), "BackgroundColor3", textColor)
            corner(track, 2)
            local fill = new("Frame", {Size = UDim2.new(0, 0, 1, 0), BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 6}, track)
            corner(fill, 2)
            bind(new("UIGradient", {Transparency = NumberSequence.new(0.6, 0)}, fill), "Color", function() return ColorSequence.new(accent()) end)
            local knob = new("Frame", {Name = "SliderKnob", Size = UDim2.fromOffset(10, 10), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, 0, 0.5, 0), BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 8, Active = true}, track)
            corner(knob, 99)
            bind(new("UIStroke", {Thickness = 3, Transparency = 0.66}, knob), "Color", accent)
            icon("glow", 26, 26, accent, knob).ImageTransparency = 0.45
            local function layout()
                local scale = math.max(targetScale, 0.1)
                local box = math.max(34, math.ceil(valueLabel.TextBounds.X / scale) + 12)
                local x = label.Position.X.Offset + math.ceil(label.TextBounds.X / scale) + 12
                valueBox.Size = UDim2.fromOffset(box, 17)
                track.Position, track.Size = UDim2.new(0, x, 0.5, 0), UDim2.new(1, -(x + box + 11), 0, 4)
            end
            layout()
            TrackGuiConnection(label:GetPropertyChangedSignal("TextBounds"):Connect(layout))
            TrackGuiConnection(label:GetPropertyChangedSignal("Position"):Connect(layout))
            TrackGuiConnection(valueLabel:GetPropertyChangedSignal("TextBounds"):Connect(layout))

            local value = data and data.Default or 0
            local step = data and data.Step or 1
            local minValue = data and data.Min or value
            local maxValue = data and data.Max or value
            local rounding = data and data.Rounding or 0

            local function roundValue(v)
                if rounding and rounding > 0 then
                    return tonumber(string.format("%." .. tostring(rounding) .. "f", v))
                end
                return math.floor(v + 0.5)
            end

            -- Persistent slider object so configs can read and restore its value.
            local sliderOption = {Value = value, IsSlider = true}

            local refresh

            function sliderOption:SetValue(newValue)
                newValue = tonumber(newValue)
                if not newValue then return false end
                value = newValue
                refresh()
                return true
            end

            function refresh()
                local clampedValue = Clamp(value, minValue, maxValue)
                value = clampedValue
                local range = maxValue - minValue
                local ratio = range == 0 and 0 or ((value - minValue) / range)
                ratio = Clamp(ratio, 0, 1)
                fill.Size = UDim2.new(ratio, 0, 1, 0)
                knob.Position = UDim2.new(ratio, 0, 0.5, 0)
                valueLabel.Text = tostring(roundValue(value))
                sliderOption.Value = value
                NexusUI.Options[id] = sliderOption
                NexusUI.Options[id .. "Value"] = value
                if data and data.Callback then
                    pcall(data.Callback, value)
                end
            end

            local dragging = false

            local function setValueFromPosition(xPosition)
                local trackStart = track.AbsolutePosition.X
                local trackSize = track.AbsoluteSize.X
                local ratio = Clamp((xPosition - trackStart) / math.max(trackSize, 1), 0, 1)
                local range = maxValue - minValue
                value = minValue + (range * ratio)
                if step and step > 0 then
                    value = roundValue(math.floor((value / step) + 0.5) * step)
                end
                refresh()
            end

            local function beginSliderDrag(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = true
                    setValueFromPosition(input.Position.X)
                end
            end

            table.insert(connections, track.InputBegan:Connect(beginSliderDrag))
            table.insert(connections, knob.InputBegan:Connect(beginSliderDrag))

            table.insert(connections, userInputService.InputChanged:Connect(function(input)
                if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                    setValueFromPosition(input.Position.X)
                end
            end))

            table.insert(connections, userInputService.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = false
                end
            end))

            refresh()
            table.insert(controls, frame)
            return frame
        end

        function tabObject:AddDropdown(id, data)
            local horizontalInset = math.max(0, tonumber(data and data.HorizontalInset) or 1)
            local selectorHeight = math.max(20, tonumber(data and data.SelectorHeight) or 28)
            local listMaxHeight = math.max(90, tonumber(data and data.ListMaxHeight) or 210)
            local optionHeight = math.max(24, tonumber(data and data.OptionHeight) or 26)
            local selectorY = 24
            local closedHeight = selectorY + selectorHeight + 8
            local listY = closedHeight

            local parent = getControlParent()
            divider(parent, "dropdown")
            local dropdownFrame = new("Frame", {Size = UDim2.new(1, 0, 0, closedHeight), BackgroundTransparency = 1, BorderSizePixel = 0, ClipsDescendants = true, LayoutOrder = #controls + 1}, parent)
            dropdownFrame:SetAttribute("BlockWindowDrag", true)
            caption(dropdownFrame, {Size = UDim2.new(1, 0, 0, 14), Position = UDim2.fromOffset(0, 6), Text = data and data.Title or id, TextSize = 9}, dimColor)
            local selector, selectorLabel = CreateClickButton(dropdownFrame, "Select...", UDim2.new(1, -(horizontalInset * 2), 0, selectorHeight), UDim2.fromOffset(horizontalInset, selectorY), COLOR_CONTROL, COLOR_TEXT, Enum.Font.GothamMedium, 10)
            selector.BackgroundTransparency = 0.3
            local selectorStroke = stroke(selector, 0.2, function() return COLOR_BORDER end)
            local dropdownStroke = selectorStroke
            selectorLabel.TextXAlignment, selectorLabel.TextTruncate = Enum.TextXAlignment.Left, Enum.TextTruncate.AtEnd
            new("UIPadding", {PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 28)}, selectorLabel)
            local arrow = icon("chevron", 10, 10, dimColor, selector)
            arrow.Position, arrow.Rotation, arrow.ZIndex = UDim2.new(1, -14, 0.5, 0), 90, 11
            local optionViews, openTween, arrowTween = {}, nil, nil
            local function refreshSelection(value)
                for v, item in pairs(optionViews) do
                    item[1]:SetAttribute("Selected", v == value)
                    item[3].Visible = v == value
                    item[4].Visible = v == value
                    item[5](false)
                end
            end

            local optionsList = bind(new("ScrollingFrame", {Size = UDim2.new(1, -(horizontalInset * 2), 0, 0), Position = UDim2.fromOffset(horizontalInset, listY), BackgroundTransparency = 0.3, BorderSizePixel = 0, ScrollBarThickness = 3, AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(), Visible = false}, dropdownFrame), "BackgroundColor3", function() return COLOR_CONTROL end)
            bind(optionsList, "ScrollBarImageColor3", function() return COLOR_BORDER end)
            corner(optionsList, 6)
            stroke(optionsList, 0.2, function() return COLOR_BORDER end)
            new("UIPadding", {PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, 2), PaddingLeft = UDim.new(0, 2), PaddingRight = UDim.new(0, 2)}, optionsList)
            new("UIListLayout", {Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder}, optionsList)

            local dropdown = {
                Value = nil,
                Values = {},
                Opened = false,
                IsDropdown = true,
            }

            local function connectActivated(guiObject, callback)
                local hitbox = Instance.new("TextButton")
                hitbox.Name = "InputHitbox"
                hitbox.Size = UDim2.fromScale(1, 1)
                hitbox.BackgroundTransparency = 1
                hitbox.BorderSizePixel = 0
                hitbox.Text = ""
                hitbox.AutoButtonColor = false
                hitbox.Active = true
                hitbox.Selectable = true
                hitbox.ZIndex = guiObject.ZIndex + 2
                hitbox.Parent = guiObject
                TrackGuiConnection(hitbox.Activated:Connect(callback))
                return hitbox
            end

            local function updateOpenState(open)
                dropdown.Opened = open == true
                local count = #dropdown.Values
                local listHeight = math.min((count * (optionHeight + 4)), listMaxHeight)
                optionsList.Visible = dropdown.Opened and count > 0
                optionsList.Size = UDim2.new(1, -(horizontalInset * 2), 0, optionsList.Visible and listHeight or 0)
                if openTween then openTween:Cancel() end
                if arrowTween then arrowTween:Cancel() end
                openTween = TweenService:Create(dropdownFrame, TweenInfo.new(0.16, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Size = UDim2.new(1, 0, 0, optionsList.Visible and (listY + listHeight + 8) or closedHeight)})
                arrowTween = TweenService:Create(arrow, TweenInfo.new(0.16, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Rotation = dropdown.Opened and -90 or 90})
                NexusUI:BindColor(dropdownStroke, "Color", function() return dropdown.Opened and ACCENT or COLOR_BORDER end)
                NexusUI:BindColor(selectorStroke, "Color", function() return dropdown.Opened and ACCENT or COLOR_BORDER end)
                openTween:Play()
                arrowTween:Play()
                if count == 0 then
                    selectorLabel.Text = "No options available"
                else
                    selectorLabel.Text = (dropdown.Value and tostring(dropdown.Value) or "Select...")
                end
            end

            local function setValue(value, invokeCallback)
                if value == nil then return false end
                local found = false
                for _, availableValue in ipairs(dropdown.Values) do
                    if availableValue == value then
                        found = true
                        break
                    end
                end
                if not found then return false end

                dropdown.Value = value
                refreshSelection(value)
                updateOpenState(false)
                if invokeCallback ~= false and data and data.Callback then
                    pcall(data.Callback, value)
                end
                return true
            end

            local function rebuildOptions()
                table.clear(optionViews)
                for _, child in ipairs(optionsList:GetChildren()) do
                    if child:IsA("GuiObject") then
                        child:Destroy()
                    end
                end

                for index, value in ipairs(dropdown.Values) do
                    local option, optionLabel = CreateClickButton(optionsList, tostring(value), UDim2.new(1, -2, 0, optionHeight), UDim2.new(), COLOR_CONTROL, COLOR_TEXT, Enum.Font.GothamMedium, 10, true)
                    option.LayoutOrder = index
                    local selected = icon("check", 11, 11, accentColor, option)
                    selected.Position, selected.ZIndex, selected.Visible = UDim2.new(1, -14, 0.5, 0), optionLabel.ZIndex, false
                    local optionAccent = bind(new("Frame", {Size = UDim2.fromOffset(2, 12), Position = UDim2.new(0, 6, 0.5, -6), BorderSizePixel = 0, Visible = false, ZIndex = optionLabel.ZIndex}, option), "BackgroundColor3", accentColor)
                    corner(optionAccent, 1)
                    local hovered, hoverTween = false, nil
                    local function color()
                        return COLOR_CONTROL:Lerp(ACCENT, option:GetAttribute("Selected") and 0.2 or hovered and 0.1 or 0)
                    end
                    NexusUI:BindColor(option, "BackgroundColor3", color)
                    local function paint(animated)
                        if hoverTween then hoverTween:Cancel() end
                        if animated then
                            hoverTween = TweenService:Create(option, TweenInfo.new(0.12), {BackgroundColor3 = color()})
                            hoverTween:Play()
                        else option.BackgroundColor3 = color() end
                    end
                    TrackGuiConnection(option.MouseEnter:Connect(function() hovered = true; paint(true) end))
                    TrackGuiConnection(option.MouseLeave:Connect(function() hovered = false; paint(true) end))
                    optionViews[value] = {option, optionLabel, selected, optionAccent, paint}
                    optionLabel.TextTruncate = Enum.TextTruncate.AtEnd
                    optionLabel.TextXAlignment = Enum.TextXAlignment.Left
                    local optionPadding = Instance.new("UIPadding")
                    optionPadding.PaddingLeft = UDim.new(0, 16)
                    optionPadding.PaddingRight = UDim.new(0, 36)
                    optionPadding.Parent = optionLabel
                    connectActivated(option, function()
                        setValue(value, true)
                    end)
                end
                refreshSelection(dropdown.Value)
                updateOpenState(dropdown.Opened)
            end

            function dropdown:SetValues(values)
                local same = #self.Values == #(values or {})
                if same then
                    for i, v in ipairs(values or {}) do if self.Values[i] ~= v then same = false; break end end
                end
                if same then return end
                self.Values = {}
                for _, value in ipairs(values or {}) do
                    table.insert(self.Values, value)
                end
                if self.Value then
                    local stillExists = false
                    for _, value in ipairs(self.Values) do
                        if value == self.Value then
                            stillExists = true
                            break
                        end
                    end
                    if not stillExists then
                        self.Value = nil
                    end
                end
                rebuildOptions()
            end

            function dropdown:SetValue(value)
                return setValue(value, true)
            end

            function dropdown:GetValue()
                return self.Value
            end

            connectActivated(selector, function()
                updateOpenState(not dropdown.Opened)
            end)

            dropdown:SetValues(data and data.Values or {})
            if data and data.Default ~= nil then
                setValue(data.Default, false)
            end

            NexusUI.Options[id] = dropdown
            table.insert(controls, dropdownFrame)
            return dropdown
        end

        function tabObject:AddButton(data)
            local hasDesc = data and data.Description and data.Description ~= ""
            local parent = getControlParent()
            divider(parent, "button")
            local buttonFrame = new("Frame", {Size = UDim2.new(1, 0, 0, hasDesc and 52 or 38), BackgroundTransparency = 1, LayoutOrder = #controls + 1, BorderSizePixel = 0, Active = true}, parent)
            buttonFrame:SetAttribute("BlockWindowDrag", true)
            local panel = bind(new("Frame", {Name = "Panel", Size = UDim2.new(1, -2, 1, -8), Position = UDim2.fromOffset(1, 4), BackgroundTransparency = 0.945, BorderSizePixel = 0}, buttonFrame), "BackgroundColor3", textColor)
            corner(panel, 7)
            local bStroke = stroke(panel, 0.91)
            caption(buttonFrame, {Size = hasDesc and UDim2.new(1, -40, 0, 14) or UDim2.new(1, -40, 1, 0), Position = UDim2.fromOffset(12, hasDesc and 11 or 0), Text = data and data.Title or "Button", TextSize = 11, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 2})
            if hasDesc then
                caption(buttonFrame, {Size = UDim2.new(1, -40, 0, 12), Position = UDim2.fromOffset(12, 27), Text = data.Description, TextSize = 9, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 2}, dimColor)
            end
            local chevron = icon("chevron", 10, 10, dimColor, buttonFrame)
            chevron.Position, chevron.ZIndex = UDim2.new(1, -15, 0.5, 0), 2
            local function paint(fillTransparency, strokeTransparency, duration)
                if not panel.Parent then return end
                TweenService:Create(panel, TweenInfo.new(duration, Enum.EasingStyle.Quad), {BackgroundTransparency = fillTransparency}):Play()
                TweenService:Create(bStroke, TweenInfo.new(duration, Enum.EasingStyle.Quad), {Transparency = strokeTransparency}):Play()
            end
            TrackGuiConnection(buttonFrame.MouseEnter:Connect(function() paint(0.9, 0.82, 0.1) end))
            TrackGuiConnection(buttonFrame.MouseLeave:Connect(function() paint(0.945, 0.91, 0.1) end))
            ConnectClick(buttonFrame, function()
                paint(0.84, 0.75, 0.07)
                task.delay(0.12, function() paint(0.945, 0.91, 0.1) end)
                if data and data.Callback then pcall(data.Callback) end
            end)
            table.insert(controls, buttonFrame)
            return buttonFrame
        end

        local featureDescriptions = {}
        local function descriptionFor(kind, id, data)
            local title = tostring(data and data.Title or id or "this setting")
            if featureDescriptions[title] then return featureDescriptions[title] end
            if title:find("Extension", 1, true) then return "Makes this movement ability travel farther." end
            if title:find("Hang Time", 1, true) then return "Keeps you in the air longer during this ability." end
            local description = data and data.Description
            if type(description) == "string" and description ~= "" then
                local text = description:lower()
                local technical = false
                for _, word in ipairs({"module", "callback", "executor", "native", "client", "server", "hook", "local ", "button", "input"}) do
                    if text:find(word, 1, true) then technical = true; break end
                end
                if not technical then return description end
            end
            local prefix = kind == "AddSlider" and "Adjusts " or kind == "AddDropdown" and "Chooses " or kind == "AddButton" and "Applies " or "Enables "
            return prefix .. title:lower() .. "."
        end
        local function addFeatureDetails(parent, text, color, expanded)
            local frame = new("Frame", {Name = "FeatureDetails", Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, BorderSizePixel = 0, ClipsDescendants = true, LayoutOrder = #controls + 1}, parent)
            frame:SetAttribute("BlockWindowDrag", true)
            local button = bind(new("TextButton", {Name = "ExpandDescription", Size = UDim2.fromOffset(62, 18), Position = UDim2.new(1, -62, 0, 0), BackgroundTransparency = 1, BorderSizePixel = 0, Text = "+ Details", TextSize = 9, AutoButtonColor = false, ZIndex = 8}, frame), "TextColor3", dimColor)
            button:SetAttribute("KeepFont", true)
            button.FontFace = TEXT_FONT
            local label = new("TextLabel", {Name = "FeatureDescription", Size = UDim2.new(1, -10, 0, 15), Position = UDim2.fromOffset(5, 21), BackgroundTransparency = 1, BorderSizePixel = 0, Text = text, Font = Enum.Font.Gotham, TextSize = 11, TextWrapped = true, TextScaled = false, TextTruncate = Enum.TextTruncate.None, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top})
            label:SetAttribute("KeepFont", true)
            bind(label, "TextColor3", function() return color or COLOR_TEXT_DIM end)
            label.Parent = frame
            local open, tween = expanded == true, nil
            local function refresh(animated)
                if not frame.Parent then return end
                if tween then tween:Cancel() end
                button.Text = open and "− Details" or "+ Details"
                label.Visible = open
                local height = 18
                if open then
                    local width = frame.AbsoluteSize.X > 10 and frame.AbsoluteSize.X - 10 or 280
                    local bounds = tabTextService:GetTextSize(label.Text, label.TextSize, Enum.Font.Gotham, Vector2.new(width, 10000))
                    local textHeight = math.max(15, math.ceil(bounds.Y) + 3)
                    label.Size = UDim2.new(1, -10, 0, textHeight)
                    height = 27 + textHeight
                end
                if animated then tween = TweenService:Create(frame, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = UDim2.new(1, 0, 0, height)}); tween:Play()
                else frame.Size = UDim2.new(1, 0, 0, height) end
            end
            TrackGuiConnection(button.Activated:Connect(function() open = not open; refresh(true) end))
            TrackGuiConnection(label:GetPropertyChangedSignal("Text"):Connect(function() refresh(false) end))
            local previousWidth = frame.AbsoluteSize.X
            TrackGuiConnection(frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                local width = frame.AbsoluteSize.X
                if width ~= previousWidth then previousWidth = width; refresh(false) end
            end))
            TrackGuiConnection(frame.Destroying:Connect(function() if tween then tween:Cancel() end end))
            table.insert(controls, frame)
            refresh(false)
            return function(value) label.Text = tostring(value or ""); refresh(false) end
        end
        for _, kind in ipairs({"AddToggle", "AddSlider", "AddDropdown", "AddButton"}) do
            local original = tabObject[kind]
            tabObject[kind] = function(self, id, data)
                if kind == "AddButton" then data = id; id = data and data.Title end
                data = data or {}
                local clean = table.clone(data)
                clean.ShowDescription, clean.Description = false, nil
                local parent = getControlParent()
                local result
                if kind == "AddButton" then result = original(self, clean) else result = original(self, id, clean) end
                decorateFeature(controls[#controls], id, data, kind)
                local setDescription = addFeatureDetails(parent, descriptionFor(kind, id, data), data.DescriptionColor, id == "PerfectShot")
                local option = id and NexusUI.Options[id]
                if kind == "AddToggle" and option then option.SetDescription = function(_, value) setDescription(value) end end
                return result
            end
        end

        local tabIndex = #tabs + 1
        if IS_MOBILE then
            TrackGuiConnection(tabButton.Activated:Connect(function()
                selectTab(tabIndex)
            end))
        else
            ConnectClick(tabButton, function()
                selectTab(tabIndex)
            end)
        end

        table.insert(tabs, {button = tabButton, page = tabPage, underline = tabUnderline})
        measureTab(tabButton)
        TrackGuiConnection(tabButton:GetPropertyChangedSignal("Text"):Connect(function() measureTab(tabButton) end))
        if tabIndex == 1 then
            selectTab(1)
        end
        return tabObject
    end

    function window:SelectTab(index)
        selectTab(index)
    end

    function window:SetCollapsed(value)
        setCollapsed(value)
    end

    function window:ToggleCollapsed()
        setCollapsed(mainFrame.Visible)
    end

    function window:SetVisible(visible)
        setVisible(visible)
    end

    function window:IsVisible()
        return mainFrame.Visible
    end

    function window:SetSize(width, height)
        if not IS_MOBILE then return false end
        local camera = Workspace.CurrentCamera
        if not camera then return false end
        local minWidth = IS_MOBILE and 320 or 430
        preferredSize = Vector2.new(
            math.clamp(math.floor(tonumber(width) or preferredSize.X), minWidth, math.max(minWidth, camera.ViewportSize.X - 16)),
            math.clamp(math.floor(tonumber(height) or preferredSize.Y), 320, math.max(320, camera.ViewportSize.Y - 64))
        )
        userResized = true
        mainFrame.Size = UDim2.fromOffset(preferredSize.X, preferredSize.Y)
        fitWindow()
        return true
    end

    function window:GetSize()
        return preferredSize.X, preferredSize.Y
    end

    track(userInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed then return end
        if input.KeyCode == toggleKey then
            window:SetVisible(not mainFrame.Visible)
        end
    end))

    local function updateRestoreVisibility()
        if not SHOW_RESTORE_BUTTON and not useCompactRestore then
            if restoreGui then
                restoreGui:Destroy()
                restoreGui = nil
            end
            return
        end

        if not mainFrame.Visible or not screenGui.Enabled then
            local mobileButtonGui = createRestoreGui()
            if mobileButtonGui then
                mobileButtonGui.Enabled = true
            end
        elseif restoreGui then
            restoreGui.Enabled = false
        end
    end

    track(mainFrame:GetPropertyChangedSignal("Visible"):Connect(function()
        updateRestoreVisibility()
    end))

    track(screenGui:GetPropertyChangedSignal("Enabled"):Connect(function()
        updateRestoreVisibility()
    end))

    if not isVisibleByDefault then
        setVisible(false)
    else
        animateWindowIn()
        updateRestoreVisibility()
    end

    local windowDestroyed = false
    destroyWindow = function()
        if windowDestroyed then
            return
        end
        windowDestroyed = true
        cancelMobileFold()

        NexusUI:UnloadFeatures()
        destroyCloseConfirm()

        for _, conn in ipairs(connections) do
            if conn and conn.Connected then
                conn:Disconnect()
            end
        end
        connections = {}
        for _, conn in ipairs(GuiConnections) do
            if conn and conn.Connected then
                conn:Disconnect()
            end
        end
        GuiConnections = {}
        if restoreGui then
            restoreGui:Destroy()
            restoreGui = nil
        end
        if screenGui and screenGui.Parent then
            screenGui:Destroy()
        end
    end

    function window:Destroy()
        destroyWindow()
    end

    return window
end

function NexusUI:CreateMinimizer()
    return nil
end

function NexusUI:Notify(options)
    local notifyGui = Instance.new("ScreenGui")
    notifyGui.Name = "NexusNotify"
    notifyGui.ResetOnSpawn = false
    notifyGui.Parent = GuiParent
    attachTextStyler(notifyGui)

    local frame = bind(new("Frame", {Size = UDim2.fromOffset(300, 54), Position = UDim2.new(1, -310, 0, 20), BackgroundTransparency = 0.04, BorderSizePixel = 0}, notifyGui), "BackgroundColor3", function() return COLOR_WINDOW end)
    corner(frame, 9)
    stroke(frame, 0.2, function() return COLOR_BORDER end)
    local accentBar = bind(new("Frame", {Size = UDim2.new(0, 3, 1, -22), Position = UDim2.fromOffset(10, 11), BorderSizePixel = 0}, frame), "BackgroundColor3", accentColor)
    corner(accentBar, 2)
    icon("glow", 17, 44, accentColor, accentBar).ImageTransparency = 0.45
    caption(frame, {Size = UDim2.new(1, -34, 1, 0), Position = UDim2.fromOffset(24, 0), Text = (options and options.Title or "Notify") .. "\n" .. (options and options.Content or ""), TextSize = 10, TextWrapped = true})

    task.delay((options and options.Duration or 3) + 0.2, function()
        if notifyGui then
            notifyGui:Destroy()
        end
    end)
end

windowSize = IS_MOBILE and UDim2.fromOffset(620, 390) or DESKTOP_WINDOW_SIZE

