    Movement = Window:AddTab({Title = "Movement"}),
    ESP = Window:AddTab({Title = "ESP"}),
    Other = Window:AddTab({Title = "Other"})
}

Tabs.Settings = Window:AddTab({ Title = "Settings"})
NexusUI:SetTheme("Noir")

Tabs.Settings:AddSection("Theme")
Tabs.Settings:AddDropdown("UITheme", {
    Title = "Color Theme",
    Values = {"Noir", "Arctic", "Amethyst", "Emerald", "Crimson"},
    Default = "Noir",
    Callback = function(value) NexusUI:SetTheme(value) end,
})

