function UpdateKeybindBadge()
    keybindBadgeLabel.Text = currentCloseKey and currentCloseKey.Name or "None"
    NexusUI:BindColor(keybindBadgeLabel, "TextColor3", function() return COLOR_TEXT end)
    TweenService:Create(keybindBadge, TweenInfo.new(0.15, Enum.EasingStyle.Quad), {
        BackgroundColor3 = COLOR_CONTROL
    }):Play()
    TweenService:Create(keybindBadgeStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad), {
        Color = COLOR_BORDER,
        Transparency = 0.4
    }):Play()
end

function SetGUIKey(key)
    if not key then return end
    currentCloseKey = key
    Window:SetToggleKey(key)
    waitingForKey = false
    UpdateKeybindBadge()
end

function BeginKeyBinding()
    waitingForKey = true
    keybindBadgeLabel.Text = "..."
    NexusUI:BindColor(keybindBadgeLabel, "TextColor3", function() return COLOR_TEXT end)
    TweenService:Create(keybindBadge, TweenInfo.new(0.15, Enum.EasingStyle.Quad), {
        BackgroundColor3 = COLOR_BORDER
    }):Play()
    TweenService:Create(keybindBadgeStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad), {
        Color = ACCENT,
        Transparency = 0.1
    }):Play()
end

TrackScriptConnection(userInputService.InputBegan:Connect(function(input, gameProcessed)
    if gameProcessed then return end
    if waitingForKey then
        if input.KeyCode == Enum.KeyCode.Escape then
            waitingForKey = false
            UpdateKeybindBadge()
            return
        end
        if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode and input.KeyCode ~= Enum.KeyCode.Unknown then
            SetGUIKey(input.KeyCode)
        elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
            SetGUIKey(Enum.KeyCode.MouseButton1)
        else
            waitingForKey = false
            UpdateKeybindBadge()
        end
    end
end))

ConnectClick(keybindBadge, function()
    if waitingForKey then
        waitingForKey = false
        UpdateKeybindBadge()
    else
        BeginKeyBinding()
    end
end)

TrackGuiConnection(keybindBadge.MouseEnter:Connect(function()
    if not waitingForKey then
        TweenService:Create(keybindBadge, TweenInfo.new(0.1, Enum.EasingStyle.Quad), {
            BackgroundColor3 = COLOR_CONTROL
        }):Play()
    end
end))

TrackGuiConnection(keybindBadge.MouseLeave:Connect(function()
    if not waitingForKey then
        TweenService:Create(keybindBadge, TweenInfo.new(0.1, Enum.EasingStyle.Quad), {
            BackgroundColor3 = COLOR_CONTROL
        }):Play()
    end
end))
end                            

                                                                                        
do
    local HttpService = game:GetService("HttpService")
    local CONFIG_ROOT = "PRIME/MarvelOmega"
    local CONFIG_FOLDER = CONFIG_ROOT .. "/Configs"
    local CONFIG_LIST_ID = "PRIME_ConfigList"
    local CONFIG_EXCLUDED = {
        [CONFIG_LIST_ID] = true,
        TeleportDropdown = true,
    }

    local function configNotify(content)
        NexusUI:Notify({Title = "Configs", Content = content, Duration = 3})
    end

    local function fileApiAvailable()
        return type(writefile) == "function" and type(readfile) == "function"
            and type(isfile) == "function" and type(listfiles) == "function"
            and type(makefolder) == "function" and type(isfolder) == "function"
    end

    local function ensureConfigFolder()
        if not fileApiAvailable() then return false end
        local ok = pcall(function()
            if not isfolder("PRIME") then makefolder("PRIME") end
            if not isfolder(CONFIG_ROOT) then makefolder(CONFIG_ROOT) end
            if not isfolder(CONFIG_FOLDER) then makefolder(CONFIG_FOLDER) end
        end)
        return ok
    end

    local function sanitizeConfigName(name)
        name = tostring(name or ""):gsub("[^%w%s%-_]", ""):gsub("^%s+", ""):gsub("%s+$", "")
        if #name > 32 then name = name:sub(1, 32) end
        return name
    end

    local function configPath(name)
        return CONFIG_FOLDER .. "/" .. name .. ".json"
    end

    local function configExists(name)
        local ok, result = pcall(isfile, configPath(name))
        return ok and result == true
    end

    local function listConfigs()
        local names = {}
        if not ensureConfigFolder() then return names end
        local ok, files = pcall(listfiles, CONFIG_FOLDER)
        if not ok or type(files) ~= "table" then return names end
        for _, path in ipairs(files) do
            local name = tostring(path):match("([^/\\]+)%.json$")
            if name then table.insert(names, name) end
        end
        table.sort(names, function(a, b) return a:lower() < b:lower() end)
        return names
    end

    local function collectConfig()
        local data = {Version = 2, Toggles = {}, Sliders = {}, Dropdowns = {}}
        for id, option in pairs(NexusUI.Options) do
            if type(option) == "table" and not CONFIG_EXCLUDED[id] then
                if option.IsToggle then
                    data.Toggles[id] = option.Value == true
                elseif option.IsSlider then
                    data.Sliders[id] = tonumber(option.Value)
                elseif option.IsDropdown and option.Value ~= nil then
                    data.Dropdowns[id] = option.IsMulti and table.clone(option.Value) or tostring(option.Value)
                end
            end
        end
        if currentCloseKey then
            data.Keybind = currentCloseKey.Name
        end
        return data
    end

    local function writeConfig(name)
        if not ensureConfigFolder() then
            configNotify("Your executor does not support file saving")
            return false
        end
        local ok, err = pcall(function()
            writefile(configPath(name), HttpService:JSONEncode(collectConfig()))
        end)
        if not ok then
            configNotify("Failed to save: " .. tostring(err))
        end
        return ok
    end

    local function applyConfig(data)
        local applied = 0

        for id, value in pairs(type(data.Sliders) == "table" and data.Sliders or {}) do
            local option = NexusUI.Options[id]
            if type(option) == "table" and option.IsSlider and option.Value ~= value then
                if pcall(function() option:SetValue(value) end) then applied += 1 end
            end
        end

        local dropdownValues = type(data.Dropdowns) == "table" and data.Dropdowns or {}
        local dropdownIds = {}
        for id in pairs(dropdownValues) do dropdownIds[#dropdownIds + 1] = id end
        table.sort(dropdownIds, function(a, b)
            local first, second = NexusUI.Options[a], NexusUI.Options[b]
            local firstOrder, secondOrder = type(first) == "table" and first.ConfigOrder or 0, type(second) == "table" and second.ConfigOrder or 0
            firstOrder, secondOrder = firstOrder or 0, secondOrder or 0
            if firstOrder ~= secondOrder then return firstOrder < secondOrder end
            return tostring(a) < tostring(b)
        end)
        for _, id in ipairs(dropdownIds) do
            local value = dropdownValues[id]
            local option = NexusUI.Options[id]
            if type(option) == "table" and option.IsDropdown and not CONFIG_EXCLUDED[id] then
                if option.IsMulti and type(value) == "table" then
                    if pcall(function() option:SetValue(value) end) then applied += 1 end
                elseif not option.IsMulti and tostring(option.Value) ~= tostring(value) then
                    for _, available in ipairs(option.Values) do
                        if tostring(available) == tostring(value) then
                            if pcall(function() option:SetValue(available) end) then applied += 1 end
                            break
                        end
                    end
                end
            end
        end

        for id, value in pairs(type(data.Toggles) == "table" and data.Toggles or {}) do
            local option = NexusUI.Toggles[id]
            if type(option) == "table" and option.Value ~= (value == true) then
                if pcall(function() option:SetValue(value == true) end) then applied += 1 end
            end
        end

        if type(data.Keybind) == "string" and not IS_MOBILE and not userInputService.TouchEnabled and type(SetGUIKey) == "function" then
            local ok, key = pcall(function() return Enum.KeyCode[data.Keybind] end)
            if ok and key then pcall(SetGUIKey, key) end
        end

        return applied
    end

    local function readConfig(name)
        if not fileApiAvailable() then
            configNotify("Your executor does not support file loading")
            return nil
        end
        if not configExists(name) then
            configNotify("Config \"" .. name .. "\" not found")
            return nil
        end
        local ok, data = pcall(function()
            return HttpService:JSONDecode(readfile(configPath(name)))
        end)
        if not ok or type(data) ~= "table" then
            configNotify("Config \"" .. name .. "\" is corrupted")
            return nil
        end
        return data
    end

    local ConfigSection = Tabs.Settings:AddSection("Configs")

                        
    local nameRow = new("Frame", {Size = UDim2.new(1, 0, 0, 46), BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = 0}, ConfigSection.Content)
    local nameField = bind(new("Frame", {Size = UDim2.new(1, -2, 0, 32), Position = UDim2.fromOffset(1, 9), BackgroundTransparency = 0.3, BorderSizePixel = 0}, nameRow), "BackgroundColor3", function() return COLOR_CONTROL end)
    corner(nameField, 7)
    local nameRowStroke = stroke(nameField, 0.4, function() return COLOR_BORDER end)
    local nameBox = bind(new("TextBox", {Size = UDim2.new(1, -20, 1, 0), Position = UDim2.fromOffset(10, 0), BackgroundTransparency = 1, ClearTextOnFocus = false, Text = "", PlaceholderText = "Config name...", TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 5}, nameField), "TextColor3", textColor)
    bind(nameBox, "PlaceholderColor3", dimColor)

    TrackGuiConnection(nameBox.Focused:Connect(function()
        nameRowStroke.Transparency = 0.1
        NexusUI:BindColor(nameRowStroke, "Color", function() return ACCENT end)
    end))
    TrackGuiConnection(nameBox.FocusLost:Connect(function()
        nameRowStroke.Transparency = 0.4
        NexusUI:BindColor(nameRowStroke, "Color", function() return COLOR_BORDER end)
    end))

    local configDropdown = Tabs.Settings:AddDropdown(CONFIG_LIST_ID, {
        Title = "Config List",
        Values = listConfigs(),
    })

    local function refreshConfigList(selectName)
        configDropdown:SetValues(listConfigs())
        if selectName then
            configDropdown:SetValue(selectName)
        end
    end

    local function getSelectedConfig()
        local selected = configDropdown:GetValue()
        if not selected then
            configNotify("Select a config first")
        end
        return selected
    end

    Tabs.Settings:AddButton({
        Title = "Create Config",
        Description = "Save current settings as a new config",
        Callback = function()
            local name = sanitizeConfigName(nameBox.Text)
            if name == "" then
                configNotify("Enter a config name")
                return
            end
            if configExists(name) then
                configNotify("\"" .. name .. "\" already exists. Use Overwrite")
                return
            end
            if writeConfig(name) then
                nameBox.Text = ""
                refreshConfigList(name)
                configNotify("Created \"" .. name .. "\"")
            end
        end,
    })

    Tabs.Settings:AddButton({
        Title = "Load Config",
        Description = "Apply the selected config",
        Callback = function()
            local name = getSelectedConfig()
            if not name then return end
            local data = readConfig(name)
            if not data then return end
            applyConfig(data)
            configNotify("Loaded \"" .. name .. "\"")
        end,
    })

    Tabs.Settings:AddButton({
        Title = "Overwrite Config",
        Description = "Save current settings into the selected config",
        Callback = function()
            local name = getSelectedConfig()
            if not name then return end
            if writeConfig(name) then
                configNotify("Overwrote \"" .. name .. "\"")
            end
        end,
    })

    Tabs.Settings:AddButton({
        Title = "Rename Config",
        Description = "Rename the selected config to the name above",
        Callback = function()
            local oldName = getSelectedConfig()
            if not oldName then return end
            local newName = sanitizeConfigName(nameBox.Text)
            if newName == "" then
                configNotify("Enter a new name above")
                return
            end
            if newName == oldName then return end
            if configExists(newName) then
                configNotify("\"" .. newName .. "\" already exists")
                return
            end
            local ok, err = pcall(function()
                writefile(configPath(newName), readfile(configPath(oldName)))
                delfile(configPath(oldName))
            end)
            if not ok then
                configNotify("Failed to rename: " .. tostring(err))
                return
            end
            nameBox.Text = ""
            refreshConfigList(newName)
            configNotify("Renamed to \"" .. newName .. "\"")
        end,
    })

    local pendingDelete, pendingDeleteTime = nil, 0
    Tabs.Settings:AddButton({
        Title = "Delete Config",
        Description = "Click twice to delete the selected config",
        Callback = function()
            local name = getSelectedConfig()
            if not name then return end
            if pendingDelete ~= name or os.clock() - pendingDeleteTime > 3 then
                pendingDelete, pendingDeleteTime = name, os.clock()
                configNotify("Click Delete again to remove \"" .. name .. "\"")
                return
            end
            pendingDelete = nil
            if type(delfile) ~= "function" then
                configNotify("Your executor does not support deleting files")
                return
            end
            local ok, err = pcall(delfile, configPath(name))
            if not ok then
                configNotify("Failed to delete: " .. tostring(err))
                return
            end
            refreshConfigList()
            configNotify("Deleted \"" .. name .. "\"")
        end,
    })

    Tabs.Settings:AddButton({
        Title = "Refresh List",
        Callback = function()
            refreshConfigList()
        end,
    })
end

end}

end)()
setfenv(NativeUI.Init, UIEnvironment)
local initialized, initializationFailure = xpcall(NativeUI.Init, function(failure)
    return debug and debug.traceback and debug.traceback(tostring(failure), 2) or tostring(failure)
end)
if not initialized then
    local partial = UIEnvironment.GuiParent and UIEnvironment.GuiParent:FindFirstChild("NexusMarvelOmegaUI")
    if partial then pcall(partial.Destroy, partial) end
    error("Marvel Omega UI initialization: " .. tostring(initializationFailure), 0)
end
assert(UIEnvironment.NexusUI and UIEnvironment.Window and UIEnvironment.Tabs, "Marvel Omega: GUI initialization failed")
local NexusUI, Window, Tabs = UIEnvironment.NexusUI, UIEnvironment.Window, UIEnvironment.Tabs
local Options = NexusUI.Options
local Player = UIEnvironment.LocalPlayer
local UserInputService = UIEnvironment.userInputService
local IS_MOBILE = UIEnvironment.IS_MOBILE
local Minimizer = nil
PrimeRuntime.UI, PrimeRuntime.Window = NexusUI, Window
UIEnvironment.RegisterUnloadCallback(Shutdown)
local function Notify(config)
    local ok, result = pcall(NexusUI.Notify, NexusUI, config)
    return ok and result or nil
end
local function bindMarvelControls(tab)
    for _, method in ipairs({"AddToggle", "AddSlider", "AddDropdown"}) do
        local native = tab[method]
        tab[method] = function(self, id, data)
            data = data or {}
            local listeners, adapted = {}, {}
            for key, value in pairs(data) do adapted[key] = value end
            adapted.Callback = function(value)
                if data.Callback then
                    local ok, failure = PrimeRuntime.Protect(data.Callback, value)
                    if not ok then error(failure, 0) end
                end
                for _, callback in ipairs(listeners) do
                    local ok, failure = PrimeRuntime.Protect(callback, value)
                    if not ok then error(failure, 0) end
                end
            end
            local control = native(self, id, adapted)
            local option = Options[id]
            assert(type(option) == "table", "Marvel Omega: missing control " .. tostring(id))
            option.Frame = type(control) == "table" and control.Frame or control
            option.ConfigOrder = tonumber(data.ConfigOrder) or 0
            function option:OnChanged(callback)
                assert(type(callback) == "function", "OnChanged expects a function")
                listeners[#listeners + 1] = callback
                PrimeRuntime.Run("UI/" .. tostring(id), function() callback(self.Value) end)
                return self
            end
            return option
        end
    end
end
for _, tab in pairs(Tabs) do bindMarvelControls(tab) end

PrimeRuntime.SilentAimSettings = {Priority = "Nearest", Preferred = {}, Ignored = {}, IgnoredAbilities = {}}
local PlayerInputModule

local function getGameModule(name)
    local modules = game:GetService("ReplicatedStorage"):FindFirstChild("Modules")
    local scriptObject = modules and modules:FindFirstChild(name)
    if not scriptObject or not scriptObject:IsA("ModuleScript") then
        return nil
    end
    local ok, result = PrimeRuntime.Protect(require, scriptObject)
    return ok and result or nil
end

local function simulateAction(action, state)
    PlayerInputModule = PlayerInputModule or getGameModule("PlayerInput")
    if not PlayerInputModule or type(PlayerInputModule.SimulateActionState) ~= "function" then
        return false
    end
    return PrimeRuntime.Protect(PlayerInputModule.SimulateActionState, PlayerInputModule, action, state)
end
